let lang = 'en';
const listeners = new Set();

export const getLang = () => lang;

export function t(key, vars = {}) {
  const s = STRINGS[lang][key] ?? STRINGS.en[key] ?? key;
  return s.replace(/\{(\w+)\}/g, (_, k) => (vars[k] ?? `{${k}}`));
}

// Picks the current language from a {en, ru} pair used in data tables.
export const tr = (pair) => (typeof pair === 'string' ? pair : pair[lang] ?? pair.en);

export function setLang(next) {
  lang = next;
  document.documentElement.lang = next;
  applyStatic();
  listeners.forEach((fn) => fn(next));
}

export const onLang = (fn) => listeners.add(fn);

export function applyStatic(root = document) {
  $$('[data-i18n]', root).forEach((node) => { node.textContent = t(node.dataset.i18n); });
}
